'use strict';
const FOCUS_OPTIONS=[
 {id:'restart',icon:'leaf',title:'Rebuild & start fresh',short:'Starting fresh',description:'Find our way back, one small step at a time.',indexes:[5,0,3]},
 {id:'communication',icon:'question',title:'Communicate better',short:'Communication',description:'Feel heard and make room for what we need.',indexes:[6,4,0]},
 {id:'distance',icon:'choice',title:'Stay close, long distance',short:'Long distance',description:'Feel part of each other’s day, wherever we are.',indexes:[7,1,2]},
 {id:'everyday',icon:'sun',title:'Connect in everyday life',short:'Everyday connection',description:'Keep making a little space for us.',indexes:[8,0,2,3,4]}
];
const TASK_IDEAS={
 restart:[['fresh-checkin','Choose a calm time for a fresh-start conversation','us','A little time to listen. We don’t need to solve everything at once.'],['fresh-intention','Write one small thing I want to do differently','me','Keep it kind, specific, and within my control.']],
 communication:[['comm-pause','Agree on how we ask for a pause','us','Choose a gentle phrase and a time to come back to the conversation.'],['comm-need','Name one thing that helps me feel heard','me','For example: a softer tone, a little patience, or reassurance.']],
 distance:[['distance-call','Plan our next call','us','Choose a time that works for both of us.'],['distance-ritual','Pick a little long-distance ritual','us','A voice note, a shared movie, or a walk while we call.']],
 everyday:[['everyday-time','Make a little phone-free time together','us','A walk, coffee, or a quiet evening counts.'],['everyday-thanks','Notice one thing I appreciate today','me','The small, ordinary things matter too.']]
};
let todoFilter='all',todoView='list';
function ensureProduct(){
 if(!Array.isArray(state.focus))state.focus=[];
 state.focus=[...new Set(state.focus.filter(k=>FOCUS_OPTIONS.some(f=>f.id===k)))];
 if(!Array.isArray(state.todos))state.todos=[];
 state.todos=state.todos.filter(t=>t&&typeof t.id==='string'&&typeof t.title==='string'&&['me','us'].includes(t.owner));
}
function initializeProduct(){ensureProduct();if(!state.focusSetupSeen)openFocus(true);}
function focusOptions(){ensureProduct();return FOCUS_OPTIONS.filter(f=>state.focus.includes(f.id));}
function focusCard(){const f=focusOptions();return `<section class="focus-summary"><div class="focus-summary-top"><span class="eyebrow">WHAT WE’RE FOCUSING ON</span>${icon('leaf')}</div><h3>${f.length?'Our relationship, our pace.':'Every season is welcome here.'}</h3><div class="focus-tags">${f.length?f.map(x=>`<span>${esc(x.short)}</span>`).join(''):'<span>Choose what would help you two</span>'}</div><p>Update this as life changes. Your memories, tasks, and progress stay with you.</p><button class="secondary" data-product="focus">${f.length?'Update our focus':'Choose our focus'} ${icon('arrow')}</button></section>`;}
function openFocus(first=false){ensureProduct();modalName=first?'focus-first':'focus';modal(first?'What brings you here?':'What matters to us now?',`<p>Starting over, finding your words, or feeling close from far away. Choose what fits your relationship today.</p><form id="focus-form"><div class="focus-options">${FOCUS_OPTIONS.map(f=>`<label class="focus-option"><input type="checkbox" name="focus" value="${f.id}" ${state.focus.includes(f.id)?'checked':''}><span class="focus-option-icon">${icon(f.icon)}</span><span class="focus-option-copy"><strong>${f.title}</strong><span>${f.description}</span></span></label>`).join('')}</div><p class="focus-hint">Choose more than one. You can change these anytime in Us.</p><p id="focus-error" class="error-text" role="alert"></p><button class="primary" type="submit">${first?'Make this our space':'Save our focus'} ${icon('arrow')}</button></form>${first?'<button class="extra-text-button full" data-product="skip-focus">Choose later</button>':''}`);}
function applyFocus(keys){ensureProduct();state.focus=[...new Set(keys.filter(k=>FOCUS_OPTIONS.some(f=>f.id===k)))];state.focusSetupSeen=true;if(!state.answer&&!state.draft.trim())state.index=focusOptions()[0]?.indexes[0]??0;persist();}
function nextMomentIndex(){const options=focusOptions();if(!options.length)return (state.index+1)%catalog.length;const pool=[...new Set(options.flatMap(f=>f.indexes))];const n=Math.floor(new Date(state.date+'T12:00:00').getTime()/86400000);const candidate=pool[n%pool.length];return candidate===state.index?pool[(n+1)%pool.length]:candidate;}
function simpleToday(){ensureProduct();const c=catalog[state.index],done=!!(state.answer&&state.partnerDone),waiting=!!state.answer&&!state.partnerDone;return `<div class="today-simple"><div class="simple-topline"><span class="date">${prettyDate(state.date,{weekday:'long',month:'short',day:'numeric'})}</span><span class="mini-streak">${icon('leaf')} ${streak()} days together</span></div><h1>A little space<br><em>for us.</em></h1><p class="simple-subtitle">You don’t have to do everything. Just find a little connection.</p>${sundayCard()}<section class="simple-moment" aria-label="Today’s Moment"><div class="simple-moment-meta"><span class="eyebrow">TODAY’S MOMENT</span><span>${done?'Both finished':waiting?'Your part is saved':'2–5 min'}</span></div><h2>${done?'You made time for each other.':waiting?'A little anticipation.':esc(c.prompt)}</h2><p>${done?'Your shared Moment is saved for you.':waiting?'Ready to open when you’ve both finished.':`${c.type} · A little way to connect today.`}</p><button class="primary" data-product="moment">${done?'Open our Moment':waiting?'View our Moment':'Make a little time'} ${icon('arrow')}</button></section><section class="partner-day-card" aria-label="Partner’s shared update"><span class="mini-avatar lilac">${esc(state.partner.charAt(0))}</span><div><div class="partner-day-title"><h2>${esc(state.partner)}’s day</h2><span>Sample update</span></div><p>A little tired. A quiet evening would feel good.</p><button class="extra-text-button" data-product="partner-update">See what they shared ${icon('chevron')}</button></div></section><button class="need-shortcut" data-extra="wellbeing">${icon('heart')}<span>Let ${esc(state.partner)} know what I need</span>${icon('arrow')}</button></div>`;}
function openMoment(){const c=catalog[state.index],done=state.answer&&state.partnerDone;modalName='moment';modal('Our daily Moment.',`<div class="card-meta"><span class="eyebrow">${prettyDate(state.date,{month:'short',day:'numeric'})}</span><span class="duration">${icon('clock')} 2–5 min</span></div>${state.revealed?reveal(c):done?ready():state.answer?waiting(c):entry(c)}${partnerStrip()}<p class="moment-modal-note">This Moment is here when you want it. Other tools live in To Do.</p>`);}
function partnerUpdate(){modalName='partner-update';modal(`${esc(state.partner)}’s day.`,`<p class="inset-note">Sample partner update. In the real app, this view would show only what your partner chooses to share.</p><div class="preview-item"><span>How I’m feeling</span><p>A little tired today.</p></div><div class="preview-item"><span>What would help</span><p>A quiet evening and a little reassurance.</p></div><p style="margin:18px 0 0;font-size:12px;color:#8b94a7">A small piece of context. You can always ask how they’re doing.</p><button class="primary" data-extra="wellbeing">Update my own day ${icon('arrow')}</button>`);}
function suggestedTasks(){const choices=focusOptions();const keys=choices.length?choices.map(f=>f.id):['everyday'];return [...new Map(keys.flatMap(k=>TASK_IDEAS[k]).map(t=>[t[0],{key:t[0],title:t[1],owner:t[2],note:t[3]}])).values()];}
function todoPage(){ensureProduct();return `${pageHeading('OUR TO DO','Small steps.<br><em>Together.</em>','Your choices, not a daily checklist. Add what helps and leave the rest.')}${selectedFeaturesSection()}${todoList()}`;}
const FEATURE_CATALOG=[
 {id:'reflection',icon:'heart',title:'Our Sunday reflection',description:'Notice the love. Make room for what could feel better.',handler:'weekly',action:'open'},
 {id:'foundations',icon:'leaf',title:'Our four foundations',description:'Emotional safety, consideration, consistency, and repair.',handler:'product',action:'foundations'},
 {id:'pause',icon:'clock',title:'Pause & reconnect',description:'Ask for space and choose a gentle time to talk again.',handler:'weekly',action:'pause'},
 {id:'wellbeing',icon:'sun',title:'How I’m doing',description:'Share a mood, a need, or a little context about your day.',handler:'extra',action:'wellbeing'},
 {id:'debrief',icon:'book',title:'After time together',description:'Reflect on a hangout. Keep it private or choose what to share.',handler:'extra',action:'debrief'},
 {id:'support',icon:'question',title:'When words are hard',description:'Find a gentle way to say what you need right now.',handler:'product',action:'support'},
 {id:'plan',icon:'clock',title:'Make time for us',description:'Plan a call, a date, or a small moment together.',handler:'product',action:'plan'},
 {id:'wearable',icon:'leaf',title:'Wearable preview',description:'Try sample Oura readings with your own sharing choices.',handler:'extra',action:'wearable'}
];
function chosenFeatures(){if(!Array.isArray(state.selectedFeatures))state.selectedFeatures=[];state.selectedFeatures=[...new Set(state.selectedFeatures.filter(id=>FEATURE_CATALOG.some(f=>f.id===id)))];return state.selectedFeatures;}
function featureTile(f,selectedOnly=false){const added=chosenFeatures().includes(f.id);return `<article class="feature-choice ${added?'feature-added':''}"><button class="tool-tile" data-${f.handler}="${f.action}"><span class="extra-icon">${icon(f.icon)}</span><span><strong>${f.title}</strong><span>${f.description}</span></span>${icon('chevron')}</button><button class="feature-toggle" data-product="toggle-feature" data-feature="${f.id}" aria-label="${added?'Remove '+f.title+' from To Do':'Add '+f.title+' to To Do'}" aria-pressed="${added}">${added?'− Remove from To Do':'+ Add to To Do'}</button></article>`;}
function toggleFeature(id){if(!FEATURE_CATALOG.some(f=>f.id===id))return;const selected=chosenFeatures(),added=selected.includes(id);state.selectedFeatures=added?selected.filter(x=>x!==id):[...selected,id];persist();render();toast(added?'Removed from To Do. Your saved entries are still here.':'Added to your To Do.');}
function featuresPage(){return `${pageHeading('OUR FEATURES','Make this<br><em>your space.</em>','Add the features you want to To Do. Remove them whenever you like.')}<p class="inset-note">Tap a feature to try it, or add it to your list for easy access. Everything is optional.</p><div class="tool-grid features-quick">${FEATURE_CATALOG.map(f=>featureTile(f)).join('')}</div>`;}
function selectedFeaturesSection(){const selected=chosenFeatures();return `<section class="selected-features"><div class="history-head"><h2>Your features · ${selected.length}</h2><button class="extra-text-button" data-action="tab" data-tab="features">Choose features</button></div>${selected.length?`<div class="tool-grid">${selected.map(id=>featureTile(FEATURE_CATALOG.find(f=>f.id===id),true)).join('')}</div>`:'<p class="feature-empty">Nothing added yet. Pick what helps you from Features.</p>'}</section>`;}

function todoList(){const tasks=state.todos.filter(t=>todoFilter==='all'||t.owner===todoFilter),open=tasks.filter(t=>!t.done),completed=tasks.filter(t=>t.done);return `<div class="todo-toolbar"><div class="filter-chips" role="group" aria-label="Filter tasks">${[['all','All'],['me','For me'],['us','For us']].map(([k,label])=>`<button class="${todoFilter===k?'selected':''}" data-product="todo-filter" data-filter="${k}" aria-pressed="${todoFilter===k}">${label}</button>`).join('')}</div><button class="add-task-button" data-product="add-task" aria-label="Add a task">+ <span>Add</span></button></div>${open.length?`<div class="task-list">${open.map(taskRow).join('')}</div>`:`<div class="todo-empty">${icon('leaf')}<h2>${completed.length?'A little breathing room.':'A fresh page for us.'}</h2><p>${completed.length?'Nothing else on this list right now.':'Add a small intention, a plan, or something you’d like to work on together.'}</p><button class="secondary" data-product="add-task">Add something that matters</button></div>`}${completed.length?`<details class="completed-tasks"><summary>Completed · ${completed.length}</summary><div class="task-list">${completed.map(taskRow).join('')}</div></details>`:''}<section class="task-suggestions"><div class="history-head"><h2>Ideas for your focus</h2><button class="extra-text-button" data-product="focus">Change focus</button></div><p class="suggestion-note">Suggestions only. Add one if it feels useful.</p>${suggestedTasks().map(s=>{const added=state.todos.some(t=>t.suggestion===s.key);return `<article class="suggestion"><div><span>${s.owner==='me'?'FOR ME':'FOR US'}</span><h3>${esc(s.title)}</h3></div><button data-product="add-suggestion" data-key="${s.key}" ${added?'disabled':''} aria-label="${added?'Added':'Add'}: ${esc(s.title)}">${added?icon('check'):'+'}</button></article>`;}).join('')}</section>`;}
function taskRow(t){return `<article class="task-row ${t.done?'task-done':''}"><button class="task-checkbox" role="checkbox" aria-checked="${!!t.done}" aria-label="${t.done?'Reopen':'Complete'}: ${esc(t.title)}" data-product="toggle-task" data-id="${esc(t.id)}"><span>${t.done?icon('check'):''}</span></button><button class="task-copy" data-product="edit-task" data-id="${esc(t.id)}"><h3>${esc(t.title)}</h3><span>${t.owner==='me'?'For me':'For us'}${t.due?' · '+esc(prettyDate(t.due,{month:'short',day:'numeric'})):''}</span></button>${icon('chevron')}</article>`;}
function taskForm(id,preset){ensureProduct();const task=state.todos.find(t=>t.id===id)||{id:'',title:preset?.title||'',note:preset?.note||'',owner:preset?.owner||'us',due:''};modalName='task';modal(task.id?'A little intention.':'What matters to you?',`<p>A plan, a conversation, a personal intention. Keep it as small as you need.</p><form id="task-form" data-id="${esc(task.id)}"><label for="task-title">What would you like to do?</label><input id="task-title" maxlength="100" required placeholder="Make time for a quiet catch-up…" value="${esc(task.title)}"><label for="task-owner">Who is this for?</label><select id="task-owner"><option value="us" ${task.owner==='us'?'selected':''}>For us</option><option value="me" ${task.owner==='me'?'selected':''}>For me</option></select><label for="task-due">A date, if you want one <span class="muted-inline">Optional</span></label><input type="date" id="task-due" value="${esc(task.due)}"><label for="task-note">A little note <span class="muted-inline">Optional</span></label><textarea id="task-note" maxlength="500" placeholder="Anything that would help…">${esc(task.note)}</textarea><p class="inset-note">“For us” is a shared-list preview. Nothing is sent to your partner in this demo.</p><p id="task-error" class="error-text" role="alert"></p><button class="primary" type="submit">${task.id?'Save changes':'Add to our list'} ${icon('check')}</button></form>`);}
function saveTask(form){const title=$('#task-title').value.trim().slice(0,100);if(!title){$('#task-error').textContent='Give your intention a little name.';return;}const due=$('#task-due').value;if(due&&!/^\d{4}-\d{2}-\d{2}$/.test(due)){$('#task-error').textContent='Choose a date or leave it blank.';return;}const prev=state.todos.find(t=>t.id===form.dataset.id);const task={...prev,id:prev?.id||'task-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8),title,owner:$('#task-owner').value==='me'?'me':'us',due,note:$('#task-note').value.trim().slice(0,500),done:prev?.done||false};if(prev)state.todos[state.todos.indexOf(prev)]=task;else state.todos.push(task);persist();closeModal();todoView='list';todoFilter='all';navigate('todo');toast('Saved to your list. Your shared streak is unchanged.');}
function addSuggestion(key){const s=suggestedTasks().find(s=>s.key===key);if(!s||state.todos.some(t=>t.suggestion===key))return;state.todos.push({id:'idea-'+key,title:s.title,note:s.note,owner:s.owner,due:'',done:false,suggestion:key});persist();render();toast('Added. You choose when to make time for it.');}
function toggleTask(id){const task=state.todos.find(t=>t.id===id);if(!task)return;task.done=!task.done;persist();render();toast(task.done?'A little step, taken.':'Back on your list.');}
function exploreTools(){return `<div class="tools-intro"><span class="eyebrow">USE WHAT HELPS</span><p>No need to complete these. They’re here when you want them.</p></div><div class="tool-grid">${[
 ['clock','Pause & reconnect','Ask for space and choose a gentle time to talk again.','pause','weekly'],
 ['sun','How I’m doing','Share a mood, a need, or a little context about your day.','wellbeing','extra'],
 ['book','After time together','Reflect on a hangout. Keep it private or choose what to share.','debrief','extra'],
 ['question','When words are hard','Find a gentle way to say what you need right now.','support','product'],
 ['clock','Make time for us','Plan a call, a date, or a small moment together.','plan','product'],
 ['leaf','Wearable preview','Try sample Oura readings with your own sharing choices.','wearable','extra']
 ].map(([i,title,desc,key,handler])=>`<button class="tool-tile" data-${handler}="${key}"><span class="extra-icon">${icon(i)}</span><span><strong>${title}</strong><span>${desc}</span></span>${icon('chevron')}</button>`).join('')}</div>`;}
function supportTool(){modalName='support';modal('When words are hard.',`<p>You don’t need the perfect explanation to ask for a little care.</p><form id="support-form"><label for="support-need">What do you need right now?</label><select id="support-need"><option>A little reassurance that we’re okay.</option><option>A pause to find my words.</option><option>Someone to listen without fixing it.</option><option>A softer, slower conversation.</option><option>A little closeness and time together.</option></select><label for="support-return">When could you reconnect? <span class="muted-inline">Optional</span></label><input id="support-return" maxlength="80" placeholder="After dinner, or in about 30 minutes…"><p class="inset-note">This saves a private note to your wellbeing card. You can choose what to share afterward. No message is sent.</p><button class="primary" type="submit">Save what I need ${icon('check')}</button></form>`);}
document.addEventListener('submit',e=>{if(e.target.id==='focus-form'){e.preventDefault();const keys=[...e.target.querySelectorAll('input[name=focus]:checked')].map(x=>x.value);if(!keys.length){$('#focus-error').textContent='Choose at least one, or choose later.';return;}applyFocus(keys);closeModal();render();toast('Our focus, updated. Your memories and progress are still here.');}if(e.target.id==='task-form'){e.preventDefault();saveTask(e.target);}if(e.target.id==='support-form'){e.preventDefault();const w=wellbeing();w.need=$('#support-need').value+($('#support-return').value.trim()?' Let’s reconnect '+$('#support-return').value.trim()+'.':'');w.share.need=false;persist();closeModal();render();openWellbeing();toast('Saved privately. Choose whether you’d like to share it.');}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-product]');if(!b)return;const a=b.dataset.product;
 if(a==='toggle-feature')toggleFeature(b.dataset.feature);else if(a==='foundations'){modalName='foundations';modal('Our four foundations.',foundationsCard());}else if(a==='focus')openFocus();else if(a==='skip-focus'){state.focusSetupSeen=true;persist();closeModal();render();}
 else if(a==='moment')openMoment();else if(a==='partner-update')partnerUpdate();
 else if(a==='todo-view'){todoView=b.dataset.view==='explore'?'explore':'list';render();}
 else if(a==='todo-filter'){todoFilter=['me','us'].includes(b.dataset.filter)?b.dataset.filter:'all';render();}
 else if(a==='add-task')taskForm();else if(a==='edit-task')taskForm(b.dataset.id);else if(a==='toggle-task')toggleTask(b.dataset.id);else if(a==='add-suggestion')addSuggestion(b.dataset.key);
 else if(a==='plan')taskForm(null,{title:'Make a little time for us',owner:'us',note:'A call, a date, a walk, or a quiet evening. Choose something that fits us.'});else if(a==='support')supportTool();
});
